const byte ldrPin = A0;
const int darkThreshold = 400; // mühitdə Serial Monitor ilə kalibrləyin

void setup() {
  Serial.begin(9600);
  pinMode(LED_BUILTIN, OUTPUT);
}

void loop() {
  const int lightValue = analogRead(ldrPin);
  digitalWrite(LED_BUILTIN, lightValue < darkThreshold ? HIGH : LOW);
  Serial.println(lightValue);
  delay(100);
}
